namespace ghidra.app.plugin.core.functiongraph.graph.vertex;

using ghidra.app.plugin.core.functiongraph.mvc;
using ghidra.program.model.address;
using ghidra.program.model.symbol;
using ghidra.util;

public class ListingFunctionGraphVertex : AbstractFunctionGraphVertex {

	private ListingGraphComponentPanel component;

	public ListingFunctionGraphVertex(FGController controller, AddressSetView addressSet,
			FlowType flowType, bool isEntry) : base(controller, controller.getProgram(), addressSet, flowType, isEntry)
    {
	}

	/** Copy constructor */
	private ListingFunctionGraphVertex(FGController controller, ListingFunctionGraphVertex vertex) : base(controller, vertex)
    {
	}

	/* @Override */
	public ListingFunctionGraphVertex cloneVertex(FGController newController) {
		return new ListingFunctionGraphVertex(newController, this);
	}

	/* @Override */
	bool hasLoadedComponent() {
		return component != null;
	}

	/* @Override */
	AbstractGraphComponentPanel doGetComponent() {
		if (component == null) {
			SystemUtilities.assertThisIsTheSwingThread(
				"Cannot create vertex component " + "off of the Swing thread");

			FGController controller = getController();
			component = new ListingGraphComponentPanel(this, controller, controller.getTool(),
				getProgram(), getAddresses());

			if (pendingRestoreColor != null) {
				component.restoreColor(pendingRestoreColor);
				pendingRestoreColor = null;
			}
		}
		return component;
	}

	/* @Override */
	public void dispose() {
		base.dispose();
		if (component != null) {
			component.dispose();
			component = null;
		}
	}
